<div class='page-header mb-3'><h2 class='page-title'>دليل الحسابات</h2></div><div class='row'><div class='col-lg-8'><div class='card table-responsive'><table class='table'><thead><tr><th>الكود</th><th>الحساب</th><th>الأب</th><th>النوع</th><th>الخصائص</th></tr></thead><tbody><?php foreach($accounts as$a):?><tr><td><?=e($a['account_code'])?></td><td><?=e($a['name_ar'])?><small class='d-block text-secondary'><?=e($a['name_en'])?></small></td><td><?=e($a['parent_code']??'—')?></td><td><?=e($a['account_type'])?></td><td><?=$a['is_postable']?'ترحيل':'تجميعي'?><?=$a['is_control']?' · رقابي':''?></td></tr><?php endforeach;?></tbody></table></div></div><div class='col-lg-4'><form class='card' method='post' action='/accounting/accounts'><div class='card-header'>إضافة حساب</div><div class='card-body'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><?php foreach(['account_code'=>'الكود','name_ar'=>'الاسم العربي','name_en'=>'الاسم الإنجليزي']as$n=>$l):?><label class='form-label'><?=$l?><input class='form-control' name='<?=$n?>' required></label><?php endforeach;?><label class='form-label'>الحساب الأب<select class='form-select' name='parent_id'><option value=''>بدون</option><?php foreach($accounts as$a):if($a['is_postable'])continue;?><option value='<?=e($a['id'])?>'><?=e($a['account_code'].' - '.$a['name_ar'])?></option><?php endforeach;?></select></label><select class='form-select mb-2' name='account_type'><?php foreach(['asset'=>'أصل','liability'=>'التزام','equity'=>'حقوق ملكية','revenue'=>'إيراد','expense'=>'مصروف']as$v=>$l):?><option value='<?=$v?>'><?=$l?></option><?php endforeach;?></select><select class='form-select mb-2' name='normal_balance'><option value='debit'>مدين</option><option value='credit'>دائن</option></select><?php foreach(['is_postable'=>'قابل للترحيل','is_control'=>'رقابي','is_active'=>'نشط']as$n=>$l):?><label class='form-check'><input class='form-check-input' type='checkbox' name='<?=$n?>' <?=$n==='is_active'?'checked':''?>><span class='form-check-label'><?=$l?></span></label><?php endforeach;?></div><div class='card-footer'><button class='btn btn-primary'>حفظ</button></div></form></div></div>
